import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import './Prediction.css';

// Your original questions for structured data collection
const questions = [
  { key: 'age', question: "Hi! Let's predict your diabetes risk. How old are you?", type: 'number', min: 0, max: 120 },
  { key: 'gender', question: "What is your gender? (Female, Male, Other)", type: 'options', options: ['Female', 'Male', 'Other'] },
  { key: 'bmi', question: "What's your BMI (Body Mass Index)?", type: 'number', min: 10, max: 50 },
  { key: 'hbA1c_level', question: "What's your HbA1c Level (%)?", type: 'number', min: 3, max: 15 },
  { key: 'blood_glucose_level', question: "What's your Blood Glucose Level (mg/dL)?", type: 'number', min: 50, max: 300 },
  { key: 'hypertension', question: "Do you have hypertension? (yes/no)", type: 'boolean' },
  { key: 'heart_disease', question: "Do you have heart disease? (yes/no)", type: 'boolean' },
  { key: 'smoking_history', question: "What is your smoking history? (never, former, current, not current, ever)", type: 'options', options: ['never', 'former', 'current', 'not current', 'ever'] },
];

// Basic fallback NLP answers for non-structured queries
const fallbackAnswers = {
  hello: "Hello! How can I assist you today?",
  help: "I'm here to help you predict diabetes risk. Let's get started!",
  thanks: "You're welcome! Feel free to ask anything else.",
  default: "Sorry, I didn't quite get that. Could you please answer the question or type 'help'?"
};

function Prediction() {
  const [messages, setMessages] = useState([{ from: 'bot', text: questions[0].question }]);
  const [currentStep, setCurrentStep] = useState(0);
  const [inputValue, setInputValue] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [answers, setAnswers] = useState({});
  const [prediction, setPrediction] = useState(null);
  const [isTyping, setIsTyping] = useState(false);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const addMessage = (from, text) => {
    setMessages(prev => [...prev, { from, text }]);
  };

  const validateInput = (value) => {
    const currentQuestion = questions[currentStep];
    if (currentQuestion.type === 'number') {
      const num = Number(value);
      if (isNaN(num)) return false;
      if (num < currentQuestion.min || num > currentQuestion.max) return false;
    }
    if (currentQuestion.type === 'boolean') {
      if (!['yes', 'no'].includes(value.toLowerCase())) return false;
    }
    if (currentQuestion.type === 'options') {
      if (!currentQuestion.options.includes(value)) return false;
    }
    return true;
  };

  // Simple fallback NLP matcher
  const fallbackNLP = (input) => {
    const lowerInput = input.toLowerCase();
    for (const key in fallbackAnswers) {
      if (lowerInput.includes(key)) return fallbackAnswers[key];
    }
    return fallbackAnswers.default;
  };

  const handleUserInput = async () => {
    const trimmedValue = inputValue.trim();
    if (!trimmedValue) return;

    addMessage('user', trimmedValue);

    // If we're still collecting structured info, validate input
    if (currentStep < questions.length) {
      if (!validateInput(trimmedValue)) {
        addMessage('bot', `Oops! That doesn't look like a valid answer. Please try again.`);
        setInputValue('');
        return;
      }

      // Save answer
      const currentQuestion = questions[currentStep];
      let val = trimmedValue;
      if (currentQuestion.type === 'number') val = Number(val);
      if (currentQuestion.type === 'boolean') val = val.toLowerCase() === 'yes' ? 1 : 0;

      const newAnswers = { ...answers, [currentQuestion.key]: val };
      setAnswers(newAnswers);
      setInputValue('');

      if (currentStep + 1 < questions.length) {
        setIsTyping(true);
        setTimeout(() => {
          addMessage('bot', questions[currentStep + 1].question);
          setCurrentStep(currentStep + 1);
          setIsTyping(false);
        }, 1000);
      } else {
        // All questions answered: send to backend
        setIsTyping(true);
        setIsLoading(true);
        try {
          const response = await axios.post('http://localhost:8000/predict', newAnswers);
          const pred = response.data;
          addMessage('bot', `Prediction: ${pred.interpretation} with ${(pred.probability * 100).toFixed(1)}% probability.`);
          addMessage('bot', pred.prediction
            ? "We recommend consulting a healthcare professional."
            : "Keep up your healthy lifestyle!");
          setPrediction(pred);
        } catch (err) {
          addMessage('bot', "Sorry, I couldn't get a prediction right now. Please try again later.");
        } finally {
          setIsTyping(false);
          setIsLoading(false);
        }
      }
    } else {
      // If structured questions done, treat input as general conversation
      setIsTyping(true);
      setTimeout(() => {
        const reply = fallbackNLP(trimmedValue);
        addMessage('bot', reply);
        setIsTyping(false);
      }, 1000);
      setInputValue('');
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !isLoading && !isTyping) {
      handleUserInput();
    }
  };

  const renderInput = () => {
    if (prediction) {
      return null; // Hide input if prediction is done
    }
    const currentQuestion = questions[currentStep];
    if (currentStep < questions.length) {
      if (currentQuestion.type === 'options') {
        return (
          <select
            value={inputValue}
            onChange={e => setInputValue(e.target.value)}
            disabled={isLoading || isTyping}
            autoFocus
          >
            <option value="">-- Select --</option>
            {currentQuestion.options.map(opt => (
              <option key={opt} value={opt}>{opt}</option>
            ))}
          </select>
        );
      }
      return (
        <input
          type={currentQuestion.type === 'number' ? 'number' : 'text'}
          placeholder="Type your answer..."
          value={inputValue}
          onChange={e => setInputValue(e.target.value)}
          onKeyDown={handleKeyPress}
          disabled={isLoading || isTyping}
          autoFocus
          autoComplete="off"
        />
      );
    } else {
      // After prediction, allow free chat input
      return (
        <input
          type="text"
          placeholder="Ask me anything or type 'help'..."
          value={inputValue}
          onChange={e => setInputValue(e.target.value)}
          onKeyDown={handleKeyPress}
          disabled={isLoading || isTyping}
          autoFocus
          autoComplete="off"
        />
      );
    }
  };

  return (
    <div className="chatbot-container">
      <h2>Diabetes Risk Prediction Chatbot</h2>
      <div className="chat-window">
        {messages.map((msg, i) => (
          <div
            key={i}
            className={`message ${msg.from}`}
            aria-live="polite"
          >
            {msg.text}
          </div>
        ))}
        {isTyping && (
          <div className="message bot typing-indicator">
            <span />
            <span />
            <span />
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {!prediction ? (
        <div className="input-area">
          {renderInput()}
          <button
            onClick={handleUserInput}
            disabled={isLoading || isTyping || !inputValue.trim()}
            aria-label="Send message"
          >
            Send
          </button>
        </div>
      ) : (
        <div className="done-message">
          <button onClick={() => window.location.reload()}>Start Over</button>
        </div>
      )}
    </div>
  );
}

export default Prediction;
